export const STATUSES=['Curious','Tried it','Practicing','Comfortable'];
export const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function filterTools(tools,{q='',family='',priority='',phase='',specialty=''}={}){const terms=q.toLocaleLowerCase().trim().split(/\s+/).filter(Boolean);return tools.filter(t=>(!family||t.family===family)&&(!priority||t.priority===priority)&&(!phase||t.start===phase)&&(!specialty||t.specialties.includes(specialty))&&terms.every(w=>[t.name,t.summary,t.why,t.family,t.kind,...t.specialties,...t.alternatives].join(' ').toLocaleLowerCase().includes(w)));}
export function cleanProgress(input,ids){if(!input||typeof input!=='object'||Array.isArray(input)||input.version!==1||(input.format!==undefined&&input.format!=='software-atlas'))throw Error('This is not a supported atlas learning-list file.');const source=input.saved;if(!source||typeof source!=='object'||Array.isArray(source))throw Error('The file has no valid learning list.');const saved={};for(const [id,value] of Object.entries(source)){if(!ids.has(id)||!value||typeof value!=='object'||Array.isArray(value))continue;const status=STATUSES.includes(value.status)?value.status:'Curious';const note=typeof value.note==='string'?value.note.slice(0,5000):'';saved[id]={status,note};}return saved;}
export function uniqueSources(tools,evidence=[]){const out=new Map();for(const entry of [...tools.flatMap(t=>t.sources),...evidence]){try{const u=new URL(entry.url);if(u.protocol==='https:'&&!out.has(u.href))out.set(u.href,{...entry,url:u.href});}catch{}}return [...out.values()].sort((a,b)=>a.title.localeCompare(b.title));}
